// === Tab: mySketch ===
var a = [];
var b = [];
var c = [];
var d = [];
var e = [];
var colors;
var n;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(89, 39, 87);
	smooth();

	n = 500;

	for(let i = 0; i < n; i++) {
		a.push(new Particle(random(width), random(height)));
		b.push(new Particle(random(width), random(height)));
		c.push(new Particle(random(width), random(height)));
		d.push(new Particle(random(width), random(height)));
		e.push(new Particle(random(width), random(height)));
	}
}

function draw() {

	noStroke();

	for(let i = 0; i < n; i++) {
		var alpha = map(i, 0, n, 0, 255);

		fill(244, 246, 246, alpha);
		a[i].display();
		a[i].move();
		a[i].checkEdges();

		fill(255, 216, 104, alpha);
		b[i].display();
		b[i].move();
		b[i].checkEdges();

		fill(248, 97, 90, alpha);
		c[i].display();
		c[i].move();
		c[i].checkEdges();

		fill(184, 13, 87, alpha);
		d[i].display();
		d[i].move();
		d[i].checkEdges();

		fill(114, 27, 101, alpha);
		e[i].display();
		e[i].move();
		e[i].checkEdges();
	}
}

function mousePressed() {
	setup();
}

class Particle {
	constructor(x, y) {
		this.pos = createVector(x, y);
		this.vel = createVector();
	}

	move() {
		let angle = noise(this.pos.y/500, this.pos.x/500) * 100;
		this.vel.set(sin(angle) / TAU, cos(angle) / TAU);
		this.pos.add(this.vel);
	}

	display() {
		ellipse(this.pos.x, this.pos.y, 2, 2);
	}

	checkEdges() {
		if(this.pos.x > width || this.pos.x < 0 || this.pos.y > height || this.pos.y < 0)
			this.pos.set(random(width), random(height));
	}

}

